struct Params {
  threshold: f32, // @default 1.2  Linear radiance where bloom starts.
  knee: f32, // @default 0.8  Softness of the threshold.
};
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let color = textureSampleLevel(inputTexture, inputSampler, uv, 0.0).rgb;
  let brightness = max(color.r, max(color.g, color.b));
  let soft = clamp(brightness - params.threshold + params.knee, 0.0, 2.0 * params.knee);
  let weight = max(soft * soft / (4.0 * params.knee + 1e-4), brightness - params.threshold) / max(brightness, 1e-4);
  return vec4f(color * weight, 1.0);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
struct Params {
  threshold: f32,
  feather: f32,
  invert: f32,
}

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let s = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  /* Single-channel depth (r32float, T959) reads .r; colour maps read luma (T974's rule). */
  let d = select(dot(s.rgb, vec3f(0.2126, 0.7152, 0.0722)), s.r, s.g + s.b < 1e-6);
  var matte = smoothstep(params.threshold - params.feather, params.threshold + params.feather, d);
  matte = select(matte, 1.0 - matte, params.invert > 0.5);
  return vec4f(matte, matte, matte, matte);
}

parameters.kernel:
struct Params {
  unproject: f32,
  fov: f32,
  inverseDepth: f32,
  near: f32,
  far: f32,
  displace: f32,
}

fn decodeDepth(sample: f32, near: f32, far: f32, inverse: f32) -> f32 {
  /* inverse (ML disparity-like): bright = close; metres via the harmonic mix.
     linear: metres via the plain mix. Both span [near, far]. */
  let s = clamp(sample, 0.0, 1.0);
  let inv = 1.0 / mix(1.0 / far, 1.0 / near, s);
  let lin = mix(near, far, s);
  return select(lin, inv, inverse > 0.5);
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let near = max(ctx.params.near, 1.0e-3);
  let far = max(ctx.params.far, near + 1.0e-3);

  /* The generator may carry more capacity than the grid (a published resolution knob
     moves cols/rows under a fixed count): every index past the grid parks far outside
     the frustum and draws nothing. */
  let cells = ctx.dim.cols * ctx.dim.rows;
  if (ctx.index >= cells) {
    q.position = vec3f(0.0, -10000.0, 0.0);
    q.tint = vec4f(0.0);
    q.depthN = 0.0;
    return q;
  }

  /* The grid generator laid points across the clip square; that xy IS the depth map's
     uv in fieldAt's own convention — one mapping, shared. */
  let sample = fieldAt(vec3f(p.position.xy, 0.0));
  /* Single-channel maps (the depth node's r32float, T959) read .r; colour depth
     visualisations (turbo, viridis) read luma; grey maps agree under both. */
  let value = select(dot(sample.rgb, vec3f(0.2126, 0.7152, 0.0722)), sample.r, sample.g + sample.b < 1e-6);
  let metres = decodeDepth(value, near, far, ctx.params.inverseDepth);
  /* T973: the decoded depth rides its own attribute to the paint kernel — the heatmap
     is a second READOUT of the axis a 2D projection hides, not a decoration. 0 = near. */
  q.depthN = clamp((metres - near) / (far - near), 0.0, 1.0);

  if (ctx.params.unproject < 0.5) {
    /* HEIGHTFIELD: near pops toward the viewer, scaled by displace. */
    let relief = (1.0 - (metres - near) / (far - near)) * ctx.params.displace;
    q.position = vec3f(p.position.xy, relief);
    return q;
  }

  /* UNPROJECTION: ray through the pixel, scaled by metres, recentred about origin. */
  let dims = vec2f(textureDimensions(fieldTexture, 0));
  let aspect = dims.x / max(dims.y, 1.0);
  let ty = tan(ctx.params.fov * 0.00872664626);  /* radians(fov) / 2 */
  let ray = vec3f(p.position.x * ty * aspect, p.position.y * ty, -1.0);
  let mid = (near + far) * 0.5;
  let scaled = ray * metres * ctx.params.displace;
  q.position = vec3f(scaled.xy, scaled.z + mid * ctx.params.displace);
  return q;
}

struct Params {
  gain: f32,
  heat: f32,
}

/* T973 — a thermal readout of depth: near burns white-hot through orange, far cools
   through magenta into deep blue. Analytic, so no second texture is needed (a point
   kernel has ONE field input, and it is carrying the colour map). */
fn thermal(t: f32) -> vec3f {
  let n = clamp(1.0 - t, 0.0, 1.0);
  return vec3f(
    smoothstep(0.0, 0.45, n),
    smoothstep(0.5, 0.9, n) * 0.8,
    smoothstep(0.0, 0.2, n) * (1.0 - smoothstep(0.25, 0.6, n)) + smoothstep(0.85, 1.0, n),
  );
}

fn process(p: Point, ctx: PointCtx) -> Point {
  var q = p;
  let cols = max(ctx.dim.cols, 2u);
  let rows = max(ctx.dim.rows, 2u);
  if (ctx.index >= cols * rows) {
    q.tint = vec4f(0.0);
    return q;
  }
  let u = f32(ctx.dim.i) / f32(cols - 1u);
  let v = f32(ctx.dim.j) / f32(rows - 1u);
  /* fieldAt speaks clip coordinates; the grid generator's layout inverted nothing, so
     the same mapping the carve kernel rode puts the colour texel under its point. */
  let colour = fieldAt(vec3f(u * 2.0 - 1.0, v * 2.0 - 1.0, 0.0));
  /* T973: photographic at heat 0, thermal at 1 — and the middle is the point: the
     source's own colour with depth bleeding through, one knob rather than a mode. */
  let blended = mix(colour.rgb, thermal(p.depthN), clamp(ctx.params.heat, 0.0, 1.0));
  /* §T977 follow-up: the field's ALPHA is honoured as COVERAGE, premultiplied — the
     colour carries the coverage, the scene renderer's own additive convention, and the
     same rule this kernel already applies at its two parked exits (tint = vec4f(0.0)).
     A masked colour map (DepthCut) now actually darkens the motes it cut. CLAMPED,
     because coverage is [0, 1] by meaning: an additive composite upstream SUMS alphas
     (measured - a lit disc over an opaque bed reads a = 2), and honouring that literally
     would double the rgb of every such point. With the clamp, any map that is
     opaque-or-over is bit-identical to the pre-fix output. */
  let cover = clamp(colour.a, 0.0, 1.0);
  q.tint = vec4f(blended * ctx.params.gain * cover, cover);
  return q;
}

parameters.source:
struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
// Stage previz — haze composite (generated by src/projects/stage-previz/haze.ts).
struct Params {
  eye: vec3f, // @default [0, 1.75, 15]  Viewing camera position (driven from the camera).
  aim: vec3f, // @default [0, 3.6, 5]  Viewing camera look-at (driven from the camera).
  fov: f32, // @default 45  Viewing camera vertical field of view, degrees (driven).
  far: f32, // @default 120  Viewing camera far plane: depth arrives as distance / far (driven).
  roll: f32, // @default 0  Viewing camera roll, degrees (driven).
  density: f32, // @default 0.03  Haze: extinction per metre (match the beam passes).
  ambient: vec3f, // @default [0.004, 0.0045, 0.006]  Light the haze carries everywhere (the room's own glow).
  reach: f32, // @default 80  Distance assumed where the ray hits nothing, metres.
  knee: f32, // @default 0.75  Highlights above this roll off softly instead of clipping.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;
@group(0) @binding(6) var inputTexture3: texture_2d<f32>;

// The camera's right vector with its ROLL, exactly as camera.ts guardedRolledUp builds a view.
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(-rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct Basis {
  f: vec3f,
  r: vec3f,
  u: vec3f,
};

fn basis(origin: vec3f, toward: vec3f, rollDeg: f32) -> Basis {
  var b: Basis;
  b.f = normalize(toward - origin);
  b.r = rolledRight(b.f, rollDeg);
  b.u = cross(b.r, b.f);
  return b;
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

fn cameraRay(cam: Basis, uv: vec2f) -> vec3f {
  let size = vec2f(textureDimensions(inputTexture1));
  let tanHalf = tan(radians(params.fov) * 0.5);
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(cam.f + cam.r * ndc.x * tanHalf * (size.x / max(size.y, 1.0)) + cam.u * ndc.y * tanHalf);
}

// Distance along the ray to the first surface, or `reach` where the ray hits nothing.
fn sceneDistance(cam: Basis, ray: vec3f, uv: vec2f, reach: f32) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far / max(dot(ray, cam.f), 1e-4), reach, d >= 0.9999 || d <= 0.0);
}

// Distance to the DRAPES (More #3: the scrim and the kabuki drawn opaque, depth only), or
// `reach`. They draw additively and write no depth, so the scene's depth runs on through them.
fn drapeDistance(cam: Basis, ray: vec3f, uv: vec2f, reach: f32) -> f32 {
  let size = vec2f(textureDimensions(inputTexture3));
  let d = textureLoad(inputTexture3, clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1)), 0).r;
  return select(d * params.far / max(dot(ray, cam.f), 1e-4), reach, d >= 0.9999 || d <= 0.0);
}

fn scatterTexel(p: vec2i) -> vec3f {
  let size = vec2i(textureDimensions(inputTexture2));
  return textureLoad(inputTexture2, clamp(p, vec2i(0), size - vec2i(1)), 0).rgb;
}

// One bilinear tap of the half-resolution scatter (More is bound unfilterable).
fn bilinear(p: vec2f) -> vec3f {
  let i = vec2i(floor(p));
  let f = p - floor(p);
  let top = mix(scatterTexel(i), scatterTexel(i + vec2i(1, 0)), f.x);
  let bottom = mix(scatterTexel(i + vec2i(0, 1)), scatterTexel(i + vec2i(1, 1)), f.x);
  return mix(top, bottom, f.y);
}

// The scatter resolved through a tent about three half-res texels wide: four bilinear taps
// half a texel apart. The beams jitter their march by interleaved gradient noise, which
// averages flat over any 3×3 block and reads as a diagonal weave over none; a plain bilinear
// upsample doubled that weave into view wherever the haze is bright (looking into a lens).
fn scatterAt(uv: vec2f) -> vec3f {
  let p = uv * vec2f(textureDimensions(inputTexture2)) - 0.5;
  return 0.25 * (bilinear(p + vec2f(-0.5, -0.5)) + bilinear(p + vec2f(0.5, -0.5)) + bilinear(p + vec2f(-0.5, 0.5)) + bilinear(p + vec2f(0.5, 0.5)));
}

fn shoulder(x: f32) -> f32 {
  let k = clamp(params.knee, 0.0, 0.99);
  return select(x, k + (1.0 - k) * (1.0 - exp(-(x - k) / (1.0 - k))), x > k);
}

@fragment
fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
  let lit = textureSampleLevel(inputTexture, inputSampler, uv, 0.0);
  let cam = basis(params.eye, params.aim, params.roll);
  let ray = cameraRay(cam, uv);
  // The render's light is faded by the haze in front of the FIRST thing it came off — a drape
  // in front of the scene included: their glow is most of what shows through them.
  let hit = min(sceneDistance(cam, ray, uv, params.reach), drapeDistance(cam, ray, uv, params.reach));
  let through = exp(-params.density * hit);
  let c = lit.rgb * through + params.ambient * (1.0 - through) + scatterAt(uv) + vec3f(frameU.time * 0.0);
  return vec4f(shoulder(c.r), shoulder(c.g), shoulder(c.b), lit.a);
}

struct SharedFrame {
  time: f32,
  deltaTime: f32,
  frameIndex: f32,
  randomSeed: f32,
  wallTime: f32,
  wallDelta: f32,
  absTime: f32,
  absFrame: f32,
  resolution: vec2f,
  pointer: vec4f,
};
// Stage previz — the DS projector's beam in haze (generated by src/projects/stage-previz/haze.ts).
struct Params {
  eye: vec3f, // @default [0, 1.75, 15]  Viewing camera position (driven from the camera).
  aim: vec3f, // @default [0, 3.6, 5]  Viewing camera look-at (driven from the camera).
  fov: f32, // @default 45  Viewing camera vertical field of view, degrees (driven).
  far: f32, // @default 120  Viewing camera far plane: depth arrives as distance / far (driven).
  roll: f32, // @default 0  Viewing camera roll, degrees (driven).
  lens: vec3f, // @default [0, 7, 20]  Projector lens position (driven from the projector).
  lensAim: vec3f, // @default [0, 6, -4]  Projector look-at (driven from the projector).
  spin: f32, // @default 0  Projector roll, degrees (driven).
  throwRatio: f32, // @default 1.8  Projector throw ratio (driven).
  aspect: f32, // @default 1.7778  Projector native aspect (driven).
  shiftX: f32, // @default 0  Lens shift X (driven).
  shiftY: f32, // @default 0  Lens shift Y (driven).
  keystoneH: f32, // @default 0  Keystone H, degrees (driven).
  keystoneV: f32, // @default 0  Keystone V, degrees (driven).
  brightness: f32, // @default 1  Projector brightness, nominal at its look-at distance (driven).
  shadowFov: f32, // @default 40  Vertical FOV of the camera that renders the projector's occluders (driven).
  shadowFar: f32, // @default 60  Far plane of that camera (driven).
  density: f32, // @default 0.03  Haze: scattering per metre.
  fog: f32, // @default 0.1  Low fog: extra scattering per metre at the deck, thinning upward.
  fogHeight: f32, // @default 0.8  Metres over which the low fog thins to a third.
  floorY: f32, // @default 1.4  The deck's height: where the low fog sits.
  drift: f32, // @default 0.6  How patchy the haze is (0 = perfectly even).
  anisotropy: f32, // @default 0.55  Forward scatter: beams read brighter looking into the lens.
  gain: f32, // @default 30  Beam visibility: how much light the haze returns.
  reach: f32, // @default 80  Longest march, metres, where the ray hits nothing.
};

@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@group(0) @binding(4) var inputTexture1: texture_2d<f32>;
@group(0) @binding(5) var inputTexture2: texture_2d<f32>;
@group(0) @binding(6) var inputTexture3: texture_2d<f32>;

const STEPS: u32 = 48u;

// The camera's right vector with its ROLL, exactly as camera.ts guardedRolledUp builds a view.
fn rolledRight(forward: vec3f, rollDeg: f32) -> vec3f {
  var up = select(vec3f(0.0, 1.0, 0.0), vec3f(0.0, 0.0, 1.0), abs(forward.y) > 0.999);
  let t = radians(-rollDeg);
  up = up * cos(t) + cross(forward, up) * sin(t) + forward * dot(forward, up) * (1.0 - cos(t));
  return normalize(cross(forward, up));
}

struct Basis {
  f: vec3f,
  r: vec3f,
  u: vec3f,
};

fn basis(origin: vec3f, toward: vec3f, rollDeg: f32) -> Basis {
  var b: Basis;
  b.f = normalize(toward - origin);
  b.r = rolledRight(b.f, rollDeg);
  b.u = cross(b.r, b.f);
  return b;
}

fn depthTexel(uv: vec2f) -> vec2i {
  let size = vec2f(textureDimensions(inputTexture1));
  return clamp(vec2i(uv * size), vec2i(0), vec2i(size) - vec2i(1));
}

fn cameraRay(cam: Basis, uv: vec2f) -> vec3f {
  let size = vec2f(textureDimensions(inputTexture1));
  let tanHalf = tan(radians(params.fov) * 0.5);
  let ndc = vec2f(uv.x * 2.0 - 1.0, 1.0 - uv.y * 2.0);
  return normalize(cam.f + cam.r * ndc.x * tanHalf * (size.x / max(size.y, 1.0)) + cam.u * ndc.y * tanHalf);
}

// Distance along the ray to the first surface, or `reach` where the ray hits nothing.
fn sceneDistance(cam: Basis, ray: vec3f, uv: vec2f, reach: f32) -> f32 {
  let d = textureLoad(inputTexture1, depthTexel(uv), 0).r;
  return select(d * params.far / max(dot(ray, cam.f), 1e-4), reach, d >= 0.9999 || d <= 0.0);
}

struct Lens {
  o: vec3f,
  f: vec3f,
  r: vec3f,
  u: vec3f,
  tx: f32,
  ty: f32,
  kx: f32,
  ky: f32,
  nominal: f32,
};

fn makeLens() -> Lens {
  let b = basis(params.lens, params.lensAim, params.spin);
  var l: Lens;
  l.o = params.lens;
  l.f = b.f;
  l.r = b.r;
  l.u = b.u;
  l.tx = 0.5 / max(params.throwRatio, 0.05);
  l.ty = l.tx / max(params.aspect, 0.05);
  l.kx = tan(radians(params.keystoneH)) / l.tx;
  l.ky = tan(radians(params.keystoneV)) / l.ty;
  l.nominal = max(length(params.lensAim - params.lens), 1e-3);
  return l;
}

// A world point through the lens: (u, v) on the cookie and the clip w (w <= 0 behind the lens).
// projectorMatrix: x = xv/tx - 2 shiftX d, w = d + kx xv + ky yv.
fn throughLens(l: Lens, q: vec3f) -> vec3f {
  let v = q - l.o;
  let xv = dot(v, l.r);
  let yv = dot(v, l.u);
  let d = dot(v, l.f);
  let w = d + l.kx * xv + l.ky * yv;
  let n = vec2f(xv / l.tx - 2.0 * params.shiftX * d, yv / l.ty - 2.0 * params.shiftY * d) / max(w, 1e-5);
  return vec3f(n.x * 0.5 + 0.5, 0.5 - n.y * 0.5, w);
}

// The direction (at unit depth) that lands on ndc corner c — the 2x2 inverse of throughLens.
fn cornerRay(l: Lens, c: vec2f) -> vec3f {
  let a = 1.0 / l.tx - c.x * l.kx;
  let b = -c.x * l.ky;
  let e = -c.y * l.kx;
  let g = 1.0 / l.ty - c.y * l.ky;
  let px = c.x + 2.0 * params.shiftX;
  let py = c.y + 2.0 * params.shiftY;
  let det = a * g - b * e;
  return l.r * ((px * g - b * py) / det) + l.u * ((a * py - e * px) / det) + l.f;
}

// The stretch [t0, t1] of the ray o + t·dir that lies inside the beam's pyramid.
fn insideBeam(l: Lens, o: vec3f, dir: vec3f, t0In: f32, t1In: f32) -> vec2f {
  var corners = array<vec3f, 4>(cornerRay(l, vec2f(-1.0, -1.0)), cornerRay(l, vec2f(1.0, -1.0)), cornerRay(l, vec2f(1.0, 1.0)), cornerRay(l, vec2f(-1.0, 1.0)));
  let centre = corners[0] + corners[1] + corners[2] + corners[3];
  var t0 = t0In;
  var t1 = t1In;
  for (var k = 0u; k < 4u; k = k + 1u) {
    var n = cross(corners[k], corners[(k + 1u) % 4u]);
    if (dot(n, centre) < 0.0) { n = -n; }
    let a = dot(n, o - l.o);
    let b = dot(n, dir);
    if (abs(b) < 1e-7) {
      if (a < 0.0) { return vec2f(1.0, 0.0); }
      continue;
    }
    if (b > 0.0) { t0 = max(t0, -a / b); } else { t1 = min(t1, -a / b); }
  }
  return vec2f(t0, t1);
}

// 1 where the lens sees q, 0 where something in front of the lens is in the way.
fn lensSees(l: Lens, q: vec3f) -> f32 {
  let v = q - l.o;
  let d = dot(v, l.f);
  let size = vec2f(textureDimensions(inputTexture2));
  let tanY = tan(radians(params.shadowFov) * 0.5);
  let tanX = tanY * size.x / max(size.y, 1.0);
  let s = vec2f(dot(v, l.r) / (d * tanX) * 0.5 + 0.5, 0.5 - dot(v, l.u) / (d * tanY) * 0.5);
  if (d <= 0.0 || s.x < 0.0 || s.x > 1.0 || s.y < 0.0 || s.y > 1.0) { return 1.0; }
  let stored = textureLoad(inputTexture2, clamp(vec2i(s * size), vec2i(0), vec2i(size) - vec2i(1)), 0).r;
  if (stored >= 0.9999 || stored <= 0.0) { return 1.0; }
  return select(0.0, 1.0, d <= stored * params.shadowFar + 0.06 + 0.004 * d);
}

fn hash(p: vec3f) -> f32 {
  var q = fract(p * 0.1031);
  q = q + dot(q, q.zyx + 31.32);
  return fract((q.x + q.y) * q.z);
}

fn valueNoise(p: vec3f) -> f32 {
  let i = floor(p);
  let f = fract(p);
  let u = f * f * (3.0 - 2.0 * f);
  let a = mix(mix(hash(i), hash(i + vec3f(1.0, 0.0, 0.0)), u.x), mix(hash(i + vec3f(0.0, 1.0, 0.0)), hash(i + vec3f(1.0, 1.0, 0.0)), u.x), u.y);
  let b = mix(mix(hash(i + vec3f(0.0, 0.0, 1.0)), hash(i + vec3f(1.0, 0.0, 1.0)), u.x), mix(hash(i + vec3f(0.0, 1.0, 1.0)), hash(i + vec3f(1.0, 1.0, 1.0)), u.x), u.y);
  return mix(a, b, u.z);
}

fn air(q: vec3f, t: f32) -> f32 {
  let wind = vec3f(0.11, 0.035, -0.06) * t;
  let n = valueNoise(q * 0.45 + wind) * 0.65 + valueNoise(q * 1.3 - wind * 1.7) * 0.35;
  let even = max(1.0 + params.drift * (n - 0.5) * 2.0, 0.0);
  let low = params.fog * exp(-max(q.y - params.floorY, 0.0) / max(params.fogHeight, 0.05)) * (0.5 + n);
  return params.density * even + low;
}

fn hg(cosTheta: f32, g: f32) -> f32 {
  let g2 = g * g;
  return (1.0 - g2) / (12.566371 * pow(max(1.0 + g2 - 2.0 * g * cosTheta, 1e-4), 1.5));
}

fn ign(pixel: vec2f) -> f32 {
  return fract(52.9829189 * fract(dot(pixel, vec2f(0.06711056, 0.00583715))));
}

@fragment
fn fs(@builtin(position) fragment: vec4f, @location(0) uv: vec2f) -> @location(0) vec4f {
  let cam = basis(params.eye, params.aim, params.roll);
  let ray = cameraRay(cam, uv);
  let hit = sceneDistance(cam, ray, uv, params.reach);
  let l = makeLens();
  let span = insideBeam(l, params.eye, ray, 0.0, hit);
  var scatter = vec3f(0.0);
  if (span.y > span.x) {
    // Jitter by THIS pass's own pixel. It renders at half the output's size, and seeding the
    // noise from uv × the output resolution stepped it two pixels per texel: interleaved
    // gradient noise at a stride of two is a slow diagonal ramp, the weave that showed
    // wherever the haze was bright.
    let jitter = ign(floor(fragment.xy) + vec2f(frameU.absFrame * 5.3, frameU.absFrame * 1.7));
    // EQUI-ANGULAR sampling about the lens (Kulla & Fajardo 2012): the samples are spaced
    // evenly in the ANGLE they subtend at the lens, not evenly along the ray. The light falls
    // off as 1/d², so the stretch of ray nearest the lens carries most of the energy; evenly
    // spaced, a pixel got one sample there or none, each carrying a huge weight and one texel
    // of the cookie — the coloured speckle fanning out of a close, wide lens. Spaced by angle
    // they crowd in where the light is, and 1/d² cancels against the sampling density exactly
    // (each sample's weight below is d² × the angle step), so the falloff adds no noise at all.
    let toLens = l.o - params.eye;
    let closest = dot(toLens, ray);
    let miss = max(length(toLens - ray * closest), 0.05);
    let a0 = atan((span.x - closest) / miss);
    let a1 = atan((span.y - closest) / miss);
    let da = (a1 - a0) / f32(STEPS);
    for (var i = 0u; i < STEPS; i = i + 1u) {
      let t = closest + miss * tan(a0 + (f32(i) + jitter) * da);
      let dt = da * (miss * miss + (t - closest) * (t - closest)) / miss;
      let q = params.eye + ray * t;
      let p = throughLens(l, q);
      if (p.z <= 0.0 || p.x < 0.0 || p.x > 1.0 || p.y < 0.0 || p.y > 1.0) { continue; }
      let seen = lensSees(l, q);
      if (seen <= 0.0) { continue; }
      let away = q - l.o;
      let d2 = max(dot(away, away), 0.01);
      let cookie = textureSampleLevel(inputTexture, inputSampler, p.xy, 0.0).rgb;
      let phase = hg(dot(away * inverseSqrt(d2), -ray), params.anisotropy);
      scatter = scatter + cookie * (params.brightness * l.nominal * l.nominal / d2 * phase * air(q, frameU.absTime) * exp(-params.density * t) * dt);
    }
  }
  scatter = scatter * params.gain;
